:root {
  --bg: #1b1b2f;
  --card: #f5f0e1;
  --ink: #1b1b2f;
  --accent: #e94f37;
  --accent-dark: #b83a28;
  --muted: #6b6b7b;
  --focus: #2f6fed;
  --radius: 0;
  --pixel: 4px;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 16px;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, #23233d 25%, transparent 25%),
    linear-gradient(-45deg, #23233d 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #23233d 75%),
    linear-gradient(-45deg, transparent 75%, #23233d 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
  font-family: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 16px;
  color: var(--ink);
}

.card {
  width: min(100%, 420px);
  background: var(--card);
  padding: 24px 20px;
  border: var(--pixel) solid var(--ink);
  box-shadow: 8px 8px 0 var(--ink);
}

h1 {
  margin: 0 0 20px;
  font-size: 28px;
  letter-spacing: 1px;
  text-transform: uppercase;
  text-align: center;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--ink);
}

.field { margin: 0 0 18px; padding: 0; border: 0; }

label, legend {
  display: block;
  margin-bottom: 6px;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

input {
  width: 100%;
  padding: 12px;
  font: inherit;
  color: var(--ink);
  background: #fff;
  border: 3px solid var(--ink);
  border-radius: 0;
  box-shadow: inset 2px 2px 0 rgba(27, 27, 47, 0.15);
}

input:hover { border-color: var(--accent-dark); }

input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  padding: 14px 8px;
  font: inherit;
  font-weight: 700;
  color: var(--ink);
  background: #fff;
  border: 3px solid var(--ink);
  border-radius: 0;
  box-shadow: 3px 3px 0 var(--ink);
  cursor: pointer;
  transition: transform 0.05s ease, box-shadow 0.05s ease, background 0.15s ease;
}

.tip-btn:hover { background: #ffe9e4; }

.tip-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(3px, 3px);
  box-shadow: 0 0 0 var(--ink);
}

.tip-btn[aria-pressed="true"] {
  color: #fff;
  background: var(--accent);
  border-color: var(--ink);
  box-shadow: 3px 3px 0 var(--ink);
}

.tip-btn[aria-pressed="true"]:hover { background: var(--accent-dark); }

.results {
  margin-top: 8px;
  padding: 16px;
  background: var(--ink);
  color: var(--card);
  border: 3px solid var(--ink);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 6px 0;
}

.total-row { border-top: 2px dashed var(--muted); margin-top: 6px; padding-top: 12px; }

.result-label { font-size: 16px; }

.result-value {
  font-size: 22px;
  font-weight: 700;
  color: #ffd166;
  white-space: nowrap;
}

.hint {
  margin: 16px 0 0;
  font-size: 14px;
  line-height: 1.5;
  color: var(--muted);
  text-align: center;
}

.error {
  margin: 6px 0 0;
  font-size: 14px;
  font-weight: 700;
  color: var(--accent-dark);
}

@media (max-width: 380px) {
  .card { padding: 20px 14px; box-shadow: 6px 6px 0 var(--ink); }
  h1 { font-size: 24px; }
  .result-value { font-size: 20px; }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var billError = document.getElementById('bill-error');
  var peopleError = document.getElementById('people-error');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));
  var tipOutput = document.getElementById('tip-per-person');
  var totalOutput = document.getElementById('total-per-person');

  var selectedTip = 15;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });

  function showError(el, message) {
    if (message) {
      el.textContent = message;
      el.hidden = false;
    } else {
      el.textContent = '';
      el.hidden = true;
    }
  }

  function setSelectedTip(value) {
    selectedTip = value;
    tipButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', String(Number(btn.dataset.tip) === value));
    });
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);
    var valid = true;

    if (billInput.value.trim() === '') {
      showError(billError, '');
    } else if (isNaN(bill) || bill < 0) {
      showError(billError, 'Enter a bill amount of 0 or more.');
      valid = false;
    } else {
      showError(billError, '');
    }

    if (peopleInput.value.trim() === '') {
      showError(peopleError, '');
    } else if (isNaN(people) || people < 1 || !Number.isInteger(people)) {
      showError(peopleError, 'Enter at least 1 person.');
      valid = false;
    } else {
      showError(peopleError, '');
    }

    if (!valid || isNaN(bill) || bill < 0 || isNaN(people) || people < 1) {
      tipOutput.textContent = money.format(0);
      totalOutput.textContent = money.format(0);
      return;
    }

    var tipTotal = bill * (selectedTip / 100);
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = (bill + tipTotal) / people;

    tipOutput.textContent = money.format(tipPerPerson);
    totalOutput.textContent = money.format(totalPerPerson);
  }

  tipButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setSelectedTip(Number(btn.dataset.tip));
      calculate();
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  setSelectedTip(15);
  calculate();
})();
